import{_ as r,o as t,c as a,a2 as o}from"./chunks/framework.Cdp8-jB6.js";const h=JSON.parse('{"title":"Capsule entry aerodynamics — sourced reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/capsule-entry-aerodynamics.md","filePath":"reference/capsule-entry-aerodynamics.md"}'),s={name:"reference/capsule-entry-aerodynamics.md"};function n(d,e,i,l,c,f){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="capsule-entry-aerodynamics-—-sourced-reference" tabindex="-1">Capsule entry aerodynamics — sourced reference <a class="header-anchor" href="#capsule-entry-aerodynamics-—-sourced-reference" aria-label="Permalink to &quot;Capsule entry aerodynamics — sourced reference&quot;">​</a></h1><blockquote><p>Library reference for the descent/entry calibration (ADR-088, <code>descent-physics.ts</code>, <code>static/data/descent-profiles/*.json</code>). Per-capsule entry aerodynamic parameters with <strong>sources</strong>, plus the flown peak-g figures used to validate the model. When a value here is pulled from an external document, its link is in the <a href="#source-library">Source library</a> below — add to that list whenever you source a new figure.</p><p>Convention: <strong>L/D</strong> = hypersonic trim lift-to-drag. <strong>BC</strong> = ballistic coefficient m/(Cd·A) (kg·m⁻²) — lower = more drag area = gentler entry. Peak-g = felt deceleration on a nominal <em>guided</em> (lifting) entry unless noted; ballistic-mode g in parentheses.</p></blockquote><h2 id="crewed-re-entry-capsules" tabindex="-1">Crewed re-entry capsules <a class="header-anchor" href="#crewed-re-entry-capsules" aria-label="Permalink to &quot;Crewed re-entry capsules&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capsule</th><th>L/D</th><th>Base Ø (m)</th><th>BC (kg·m⁻²)</th><th>Flown peak-g (LEO)</th><th>Flown peak-g (lunar)</th><th>Sources</th></tr></thead><tbody><tr><td><strong>Apollo CM</strong></td><td>0.30</td><td>3.91</td><td><strong>313.5</strong> (sourced)</td><td>~3.3 g (Apollo 7)</td><td>~6.5–8 g (skip)</td><td><a href="https://www.researchgate.net/figure/Aerodynamic-coefficients-for-Apollo-command-capsule-a-Drag-coefficient-b-Lift_fig16_268557220" target="_blank" rel="noreferrer">NASA aero</a>, <a href="https://www.faa.gov/sites/faa.gov/files/about/office_org/headquarters_offices/avs/III.4.1.7_Returning_from_Space.pdf" target="_blank" rel="noreferrer">FAA/NASA</a>, <a href="https://www.asme.org/wwwasmeorg/media/resourcefiles/aboutasme/who%20we%20are/engineering%20history/landmarks/162-apollo-space-command-module.pdf" target="_blank" rel="noreferrer">ASME</a></td></tr><tr><td><strong>Soyuz DM</strong></td><td>0.30</td><td>2.17</td><td>~530 (derived)</td><td>3–4 g</td><td>~8 g</td><td><a href="https://prokosmos.ru/2025/11/28/kosmicheskij-korabl-soyuz" target="_blank" rel="noreferrer">prokosmos (RU)</a>, <a href="http://transport.kaketoustroeno.ru/a_transport&amp;spuskaemiy-apparat&amp;1.htm" target="_blank" rel="noreferrer">kaketoustroeno (RU)</a></td></tr><tr><td><strong>Shenzhou RV</strong></td><td>≥0.20</td><td>2.52</td><td>~440 (derived)</td><td>≤4 g (bank-steered, ~20° trim)</td><td>(skip design)</td><td><a href="https://news.qq.com/rain/a/20241105A01HC000" target="_blank" rel="noreferrer">Tencent explainer (CN)</a>, <a href="https://jdse.bit.edu.cn/sktcxb/cn/article/pdf/preview/10.15982/j.issn.2096-9287.2021.20210016.pdf" target="_blank" rel="noreferrer">jdse skip-entry (CN)</a></td></tr><tr><td><strong>Crew Dragon</strong></td><td>0.18</td><td>3.66</td><td>~500 (derived)</td><td>~4 g</td><td>—</td><td><a href="https://repository.gatech.edu/server/api/core/bitstreams/39f02e86-13a2-4066-a79d-2a87df7d2ccd/content" target="_blank" rel="noreferrer">Georgia Tech</a></td></tr><tr><td><strong>Gemini RM</strong></td><td>0.19</td><td>2.28</td><td>~330 (derived)</td><td>~5–8 g</td><td>—</td><td><a href="https://apps.dtic.mil/sti/tr/pdf/AD0856691.pdf" target="_blank" rel="noreferrer">DTIC AD0856691</a></td></tr><tr><td><strong>Mercury</strong> (orbital)</td><td>0 (ballistic)</td><td>1.89</td><td>—</td><td>~7.8 g</td><td>—</td><td><a href="https://www.faa.gov/sites/faa.gov/files/about/office_org/headquarters_offices/avs/III.4.1.7_Returning_from_Space.pdf" target="_blank" rel="noreferrer">FAA/NASA</a></td></tr><tr><td><strong>Mercury</strong> (suborbital)</td><td>0 (ballistic)</td><td>1.89</td><td>—</td><td>~11 g (Redstone hop)</td><td>—</td><td><a href="https://www.faa.gov/sites/faa.gov/files/about/office_org/headquarters_offices/avs/III.4.1.7_Returning_from_Space.pdf" target="_blank" rel="noreferrer">FAA/NASA</a></td></tr><tr><td><strong>Vostok / Voskhod</strong></td><td>0 (ballistic)</td><td>2.30</td><td>—</td><td>~8 g</td><td>—</td><td><a href="https://www.faa.gov/sites/faa.gov/files/about/office_org/headquarters_offices/avs/III.4.1.7_Returning_from_Space.pdf" target="_blank" rel="noreferrer">FAA/NASA</a></td></tr><tr><td><strong>MSL / Curiosity</strong> (Mars)</td><td>0.24</td><td>4.5</td><td>~140 (Cd·A 24)</td><td>—</td><td>~12 g (Mars entry)</td><td><a href="https://ntrs.nasa.gov/api/citations/20110003649/downloads/20110003649.pdf" target="_blank" rel="noreferrer">MSL guidance</a></td></tr></tbody></table><p>Notes:</p><ul><li><strong>Apollo CM BC 313.5 kg·m⁻²</strong> is directly sourced (NASA aero data, ref area 12.0 m², 3.91 m base → Cd·A 17.7, Cd ≈ 1.47). This calibrates the blunt-body Cd used to <em>derive</em> the others&#39; Cd·A from their published base diameters — those BCs are marked &quot;derived&quot; (model estimates).</li><li><strong>L/D is directly sourced for most lifting capsules</strong> (see per-capsule links). Apollo &amp; Soyuz share the 0.3 &quot;offset-CG / headlight&quot; value; Dragon is lowest at 0.18 (12° trim); Gemini 0.19; Shenzhou ≥0.2; MSL/Curiosity 0.24. <strong>Exceptions (MSL-class estimates, marked in <code>estimatedFields</code>):</strong> Perseverance + Tianwen-1 reuse the MSL aeroshell so we take L/D 0.24, but a mission-specific figure is not directly cited for them.</li><li><strong>Ballistic capsules</strong> (Mercury/Vostok/Voskhod) have no lift — an offset-CG lift vector was not yet used; they ate the full ~8 g. Correct to keep them lift-free.</li><li><strong>Suborbital gap (honest):</strong> the two Mercury-Redstone hops (freedom-7, liberty-bell-7) read ~8.7 g in the model vs the flown ~11 g. Their 18° entry angle + drag area are model estimates (marked in <code>estimatedFields</code>), unclosed — a known low-fidelity corner, not a sourced match.</li></ul><h2 id="how-the-orrery-model-uses-these" tabindex="-1">How the Orrery model uses these <a class="header-anchor" href="#how-the-orrery-model-uses-these" aria-label="Permalink to &quot;How the Orrery model uses these&quot;">​</a></h2><ul><li>Profiles set <code>liftToDragRatio</code> (sourced), <code>entryCdA</code> (Apollo sourced, others geometry-derived), <code>flightPathAngleDeg</code> (~1.5° LEO deorbit, estimate), <code>targetDownrangeKm</code> (estimate). The estimated fields are declared in each profile&#39;s <code>estimatedFields</code>; a test enforces it (ADR-088 Phase 0b/1a).</li><li><strong>Known model gap (honest):</strong> the range-control solve flies a single <em>fixed</em> bank, so modeled guided peak-g runs <strong>above</strong> the flown value for low-L/D capsules — Apollo 4.2 g (flown 3.3), Soyuz <strong>5.6 g</strong> (flown 3–4), Shenzhou 5.0 g (flown ≤4), Dragon 5.3 g (flown ~4); i.e. <strong>+1 to +2.6 g</strong>. Real vehicles actively bank-<em>modulate</em> to hold a g-limit. <strong>Measured negative result:</strong> wiring the kernel&#39;s own decel-hold controller (<code>bankLiftFraction</code>) does NOT close this — it <em>overshoots</em> (Apollo target 3 g → peak ~6 g, worse than the fixed bank&#39;s ~4.2 g), because early in entry, with g below target, it digs <em>in</em> to build g. Holding a target g genuinely needs a predictor-corrector (integrate-ahead) controller, which is a large build; the residual stands documented, not faked. Separately, at lunar-return energy the capsule <em>lofts/skips</em>, which the #29 loft model DOES reproduce (ADR-089).</li></ul><h2 id="source-library" tabindex="-1">Source library <a class="header-anchor" href="#source-library" aria-label="Permalink to &quot;Source library&quot;">​</a></h2><ul><li><a href="https://www.researchgate.net/figure/Aerodynamic-coefficients-for-Apollo-command-capsule-a-Drag-coefficient-b-Lift_fig16_268557220" target="_blank" rel="noreferrer">apollo-aero</a>: Apollo command capsule aerodynamic coefficients (drag/lift) — <a href="https://www.researchgate.net/figure/Aerodynamic-coefficients-for-Apollo-command-capsule-a-Drag-coefficient-b-Lift_fig16_268557220" target="_blank" rel="noreferrer">https://www.researchgate.net/figure/Aerodynamic-coefficients-for-Apollo-command-capsule-a-Drag-coefficient-b-Lift_fig16_268557220</a></li><li><a href="https://www.faa.gov/sites/faa.gov/files/about/office_org/headquarters_offices/avs/III.4.1.7_Returning_from_Space.pdf" target="_blank" rel="noreferrer">faa</a>: FAA/NASA &quot;Returning from Space: Re-entry&quot; (LEO vs lunar g-loads) — <a href="https://www.faa.gov/sites/faa.gov/files/about/office_org/headquarters_offices/avs/III.4.1.7_Returning_from_Space.pdf" target="_blank" rel="noreferrer">https://www.faa.gov/sites/faa.gov/files/about/office_org/headquarters_offices/avs/III.4.1.7_Returning_from_Space.pdf</a></li><li><a href="https://www.asme.org/wwwasmeorg/media/resourcefiles/aboutasme/who%20we%20are/engineering%20history/landmarks/162-apollo-space-command-module.pdf" target="_blank" rel="noreferrer">asme</a>: ASME Apollo Command Module landmark (lunar-return entry) — <a href="https://www.asme.org/wwwasmeorg/media/resourcefiles/aboutasme/who%20we%20are/engineering%20history/landmarks/162-apollo-space-command-module.pdf" target="_blank" rel="noreferrer">https://www.asme.org/wwwasmeorg/media/resourcefiles/aboutasme/who we are/engineering history/landmarks/162-apollo-space-command-module.pdf</a></li><li><a href="https://prokosmos.ru/2025/11/28/kosmicheskij-korabl-soyuz" target="_blank" rel="noreferrer">soyuz-ru</a>: prokosmos.ru — Союз: устройство и спуск (L/D 0.3, g-loads) — <a href="https://prokosmos.ru/2025/11/28/kosmicheskij-korabl-soyuz" target="_blank" rel="noreferrer">https://prokosmos.ru/2025/11/28/kosmicheskij-korabl-soyuz</a></li><li><a href="http://transport.kaketoustroeno.ru/a_transport&amp;spuskaemiy-apparat&amp;1.htm" target="_blank" rel="noreferrer">soyuz-ru2</a>: kaketoustroeno.ru — Спускаемый аппарат: аэродинамическое торможение — <a href="http://transport.kaketoustroeno.ru/a_transport&amp;spuskaemiy-apparat&amp;1.htm" target="_blank" rel="noreferrer">http://transport.kaketoustroeno.ru/a_transport&amp;spuskaemiy-apparat&amp;1.htm</a></li><li><a href="https://news.qq.com/rain/a/20241105A01HC000" target="_blank" rel="noreferrer">sz-cn</a>: Tencent News — 神舟载人飞船是如何返回地面的 (L/D ≥0.2, ≤4 g bank-steer) — <a href="https://news.qq.com/rain/a/20241105A01HC000" target="_blank" rel="noreferrer">https://news.qq.com/rain/a/20241105A01HC000</a></li><li><a href="https://jdse.bit.edu.cn/sktcxb/cn/article/pdf/preview/10.15982/j.issn.2096-9287.2021.20210016.pdf" target="_blank" rel="noreferrer">sz-skip</a>: 深空探测跳跃式再入返回任务设计 (lunar-return skip-entry design, CN) — <a href="https://jdse.bit.edu.cn/sktcxb/cn/article/pdf/preview/10.15982/j.issn.2096-9287.2021.20210016.pdf" target="_blank" rel="noreferrer">https://jdse.bit.edu.cn/sktcxb/cn/article/pdf/preview/10.15982/j.issn.2096-9287.2021.20210016.pdf</a></li><li><a href="https://repository.gatech.edu/server/api/core/bitstreams/39f02e86-13a2-4066-a79d-2a87df7d2ccd/content" target="_blank" rel="noreferrer">gatech</a>: Georgia Tech — SpaceX Dragon Re-Entry Vehicle: Aerodynamics (L/D 0.18, 12° trim) — <a href="https://repository.gatech.edu/server/api/core/bitstreams/39f02e86-13a2-4066-a79d-2a87df7d2ccd/content" target="_blank" rel="noreferrer">https://repository.gatech.edu/server/api/core/bitstreams/39f02e86-13a2-4066-a79d-2a87df7d2ccd/content</a></li><li><a href="https://apps.dtic.mil/sti/tr/pdf/AD0856691.pdf" target="_blank" rel="noreferrer">dtic-gemini</a>: DTIC AD0856691 — Hypersonic Aerodynamic Characteristics of the Gemini Re-Entry Module — <a href="https://apps.dtic.mil/sti/tr/pdf/AD0856691.pdf" target="_blank" rel="noreferrer">https://apps.dtic.mil/sti/tr/pdf/AD0856691.pdf</a></li></ul><hr><p><em>Orrery · docs/reference/capsule-entry-aerodynamics.md · created 2026-08-31 (ADR-088 Phase 1a)</em></p>',12)])])}const g=r(s,[["render",n]]);export{h as __pageData,g as default};
